import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

final class EventBus {
    private final Map<Class<? extends PaymentEvent>, List<Consumer<PaymentEvent>>> handlers = new HashMap<>();

    // Consumer<? super E>: a handler for E or for any supertype of E
    <E extends PaymentEvent> void subscribe(Class<E> type, Consumer<? super E> handler) {
        handlers.computeIfAbsent(type, t -> new ArrayList<>()).add(event -> {
            if (type.isInstance(event)) handler.accept(type.cast(event));   // the adapter
        });
    }

    int publish(PaymentEvent event) {
        List<Consumer<PaymentEvent>> list = handlers.getOrDefault(event.getClass(), List.of());
        list.forEach(h -> h.accept(event));
        return list.size();
    }
}

// bus.subscribe(CardAuthorized.class, e -> fraudCheck(e));

