fun parseWebhook(body: Map<*, *>): Either<String, PaymentEvent> {
    val id = body["id"] as? String ?: return Either.Left("missing id")
    val cents = (body["cents"] as? Number)?.toLong() ?: return Either.Left("missing cents")
    return when (body["type"]) {
        "auth" -> Either.Right(CardAuthorized(id, cents))
        "refund" -> Either.Right(RefundIssued(id, cents))
        else -> Either.Left("unknown type ${body["type"]}")
    }
}

steps.alt_code:
static Either<String, PaymentEvent> parseWebhook(Map<?, ?> body) {
    if (!(body.get("id") instanceof String id)) return new Left<>("missing id");
    if (!(body.get("cents") instanceof Number n)) return new Left<>("missing cents");
    long cents = n.longValue();
    Object type = body.get("type");
    if ("auth".equals(type)) return new Right<>(new CardAuthorized(id, cents));
    if ("refund".equals(type)) return new Right<>(new RefundIssued(id, cents));
    return new Left<>("unknown type " + type);
}

