val LAST_ERROR = key<String>("webhook.lastError")

fun handle(body: Map<*, *>, bus: EventBus, context: Attributes): Int =
    when (val parsed = parseWebhook(body)) {
        is Either.Right -> bus.publish(parsed.value)              // events flow out to the handlers
        is Either.Left -> { context[LAST_ERROR] = parsed.value; 0 }
    }

steps.alt_code:
static final Key<String> LAST_ERROR = Key.of("webhook.lastError", new TypeRef<String>() {});

static int handle(Map<?, ?> body, EventBus bus, Attributes context) {
    return switch (parseWebhook(body)) {
        case Right<String, PaymentEvent> r -> bus.publish(r.value());
        case Left<String, PaymentEvent> l -> { context.set(LAST_ERROR, l.value()); yield 0; }
    };
}

